Write-Section "Static Kotlin integrity checks"

$duplicateImports = New-Object System.Collections.Generic.List[string]
$packageMismatches = New-Object System.Collections.Generic.List[string]
$javaRoot = Join-Path $AndroidRoot "app\src\main\java"

Get-ChildItem -LiteralPath $javaRoot -Filter "*.kt" -File -Recurse |
    ForEach-Object {
        $filePath = $_.FullName
        $lines = @(Get-Content -LiteralPath $filePath)

        $imports = @(
            $lines |
                ForEach-Object { $_.Trim() } |
                Where-Object { $_.StartsWith("import ") }
        )

        foreach ($group in @(
            $imports |
                Group-Object |
                Where-Object { $_.Count -gt 1 }
        )) {
            $duplicateImports.Add(
                $filePath + " -> " + [string]$group.Name
            )
        }

        $packageLine = $lines |
            ForEach-Object { $_.Trim() } |
            Where-Object { $_.StartsWith("package ") } |
            Select-Object -First 1

        if ($packageLine) {
            $declared = $packageLine.Substring(8).Replace(
                [string][char]96,
                ""
            )
            $relativeDirectory = Split-Path -Parent (
                $filePath.Substring($javaRoot.Length).TrimStart("\")
            )
            $expected = $relativeDirectory.Replace("\", ".")

            if ($declared -ne $expected) {
                $packageMismatches.Add(
                    $filePath +
                    " -> declared=" +
                    $declared +
                    ", expected=" +
                    $expected
                )
            }
        }
        else {
            $packageMismatches.Add(
                $filePath + " -> no package declaration"
            )
        }
    }

if ($duplicateImports.Count -gt 0) {
    throw (
        "Duplicate Kotlin imports found: " +
        ($duplicateImports -join "; ")
    )
}
Write-Host "[PASS] No duplicate Kotlin imports" -ForegroundColor Green

if ($packageMismatches.Count -gt 0) {
    throw (
        "Kotlin package/path mismatches found: " +
        ($packageMismatches -join "; ")
    )
}
Write-Host (
    "[PASS] Kotlin package declarations match source paths"
) -ForegroundColor Green

$sourceText = (
    Get-ChildItem -LiteralPath $javaRoot -Filter "*.kt" -File -Recurse |
        ForEach-Object {
            Get-Content -LiteralPath $_.FullName -Raw
        }
) -join "`n"

foreach ($pattern in @(
    'AIza[0-9A-Za-z_-]{20,}',
    'gsk_[0-9A-Za-z]{20,}',
    'sk-[0-9A-Za-z]{20,}',
    'ghp_[0-9A-Za-z]{20,}'
)) {
    if ($sourceText -match $pattern) {
        throw "A recognized hard-coded credential pattern was found."
    }
}

Write-Host (
    "[PASS] No recognized hard-coded API key pattern"
) -ForegroundColor Green

if ($sourceText.IndexOf([char]8) -ge 0) {
    throw "A hidden backspace character was found in Kotlin source."
}

Write-Host (
    "[PASS] No hidden control character from regex escaping"
) -ForegroundColor Green

Write-Host ""
Write-Host (
    "AURA v0.8.3 source and payload validation passed."
) -ForegroundColor Green
Write-Host ("Backup: " + $BackupRoot)
Write-Host (
    "Rollback: " +
    (Join-Path $BackupRoot "RESTORE-AURA-v0.8.3.ps1")
)

if ($SkipBuild) {
    Write-Host ""
    Write-Host "Build skipped by request." -ForegroundColor Yellow
    exit 0
}

$JavaHome = Find-AndroidStudioJava

if (-not $JavaHome) {
    throw (
        "Java was not found. Keep Android Studio open and run this updater again."
    )
}

$JavaMajor = Get-JavaMajorVersion -JavaHome $JavaHome

if ($JavaMajor -lt 17) {
    throw (
        "Java " +
        [string]$JavaMajor +
        " was found, but Java 17 or newer is required."
    )
}

Write-Host (
    "[PASS] Java " +
    [string]$JavaMajor +
    " found at " +
    $JavaHome
) -ForegroundColor Green

$env:JAVA_HOME = $JavaHome
$env:Path = (Join-Path $JavaHome "bin") + ";" + $env:Path

Write-Section "Building and testing AURA v0.8.3"

$BuildLog = Join-Path $LogRoot (
    "gradle-v0.8.3-command-reliability.log"
)
$StdoutPath = Join-Path $LogRoot "gradle.stdout.tmp"
$StderrPath = Join-Path $LogRoot "gradle.stderr.tmp"

$GradleArguments = @(
    "--no-daemon",
    "--console=plain",
    ":app:clean",
    ":app:compileDebugKotlin",
    ":app:testDebugUnitTest",
    ":app:lintDebug",
    ":app:assembleDebug",
    ":app:assembleDebugAndroidTest"
)

try {
    $GradleProcess = Start-Process `
        -FilePath $GradleWrapper `
        -ArgumentList $GradleArguments `
        -WorkingDirectory $AndroidRoot `
        -Wait `
        -PassThru `
        -NoNewWindow `
        -RedirectStandardOutput $StdoutPath `
        -RedirectStandardError $StderrPath

    $OutputLines = New-Object System.Collections.Generic.List[string]

    if (Test-Path -LiteralPath $StdoutPath -PathType Leaf) {
        foreach ($line in Get-Content -LiteralPath $StdoutPath) {
            $OutputLines.Add([string]$line)
        }
    }

    if (Test-Path -LiteralPath $StderrPath -PathType Leaf) {
        foreach ($line in Get-Content -LiteralPath $StderrPath) {
            $OutputLines.Add([string]$line)
        }
    }

    [System.IO.File]::WriteAllLines(
        $BuildLog,
        [string[]]$OutputLines,
        (New-Object System.Text.UTF8Encoding($false))
    )

    if ($GradleProcess.ExitCode -ne 0) {
        Write-Host ""
        Write-Host "AURA v0.8.3 build failed." -ForegroundColor Red

        $errors = @(
            $OutputLines |
                Where-Object {
                    $_ -match (
                        "^(e:|error:|FAILURE:|" +
                        "Execution failed|Caused by:)"
                    )
                } |
                Select-Object -First 24
        )

        if ($errors.Count -gt 0) {
            Write-Host "First relevant errors:" -ForegroundColor Yellow

            foreach ($item in $errors) {
                Write-Host ([string]$item)
            }
        }

        Write-Host ("Complete build log: " + $BuildLog)
        Write-Host (
            "Rollback: " +
            (Join-Path $BackupRoot "RESTORE-AURA-v0.8.3.ps1")
        )
        exit $GradleProcess.ExitCode
    }
}
finally {
    Remove-Item -LiteralPath $StdoutPath `
        -Force `
        -ErrorAction SilentlyContinue
    Remove-Item -LiteralPath $StderrPath `
        -Force `
        -ErrorAction SilentlyContinue
}

$ApkPath = Join-Path $AndroidRoot (
    "app\build\outputs\apk\debug\app-debug.apk"
)

if (-not (Test-Path -LiteralPath $ApkPath -PathType Leaf)) {
    throw (
        "Gradle succeeded, but the debug APK was not found: " +
        $ApkPath
    )
}

$ApkSizeMb = [math]::Round(
    (Get-Item -LiteralPath $ApkPath).Length / 1MB,
    2
)

Write-Host ""
Write-Host (
    "AURA v0.8.3 BUILD AND TESTS SUCCESSFUL"
) -ForegroundColor Green
Write-Host ("APK: " + $ApkPath)
Write-Host (
    "APK size: " +
    [string]$ApkSizeMb +
    " MB"
)
Write-Host ("Build log: " + $BuildLog)
Write-Host ""
Write-Host (
    "Install through Android Studio Run without uninstalling AURA."
) -ForegroundColor Cyan
Write-Host (
    "First test with Whisper language set to English."
)
Write-Host (
    "Test: open YouTube and play Patar Basori"
)
Write-Host (
    "Test: remain silent after tapping the microphone"
)
